function render(root, props, fire) {
  var steps = (props.steps || []).filter(function (s) { return s && s.label != null && isFinite(+s.value); });
  var unit = props.unit == null ? '$' : props.unit;
  var sel = props.selected || '';
  function fmt(v) {
    var a = Math.abs(v), s = a >= 1e9 ? (a / 1e9).toFixed(1) + 'B' : a >= 1e6 ? (a / 1e6).toFixed(1) + 'M' : a >= 1e3 ? (a / 1e3).toFixed(1) + 'K' : a.toFixed(0);
    return (v < 0 ? '-' : '') + unit + s.replace('.0', '');
  }
  root.querySelector('.title').textContent = props.title || '';
  // running totals
  var run = 0, bars = [];
  steps.forEach(function (s) {
    var v = +s.value, from, to;
    if (s.kind === 'total') { from = 0; to = v; run = v; }
    else { from = run; run += v; to = run; }
    bars.push({ s: s, v: v, from: from, to: to, run: run });
  });
  root.querySelector('.tvalue').textContent = bars.length ? fmt(bars[bars.length - 1].run) : '';
  var svg = root.querySelector('.chart'), area = svg.parentNode;
  var W = Math.max(200, area.clientWidth), H = Math.max(80, area.clientHeight);
  svg.setAttribute('viewBox', '0 0 ' + W + ' ' + H);
  var tip = root.querySelector('.tip');
  if (!bars.length) { svg.innerHTML = '<text x="' + W / 2 + '" y="' + H / 2 + '" text-anchor="middle">No data</text>'; return; }
  var lo = 0, hi = 0;
  bars.forEach(function (b) { lo = Math.min(lo, b.from, b.to); hi = Math.max(hi, b.from, b.to); });
  var span = (hi - lo) || 1, T = 18, B = 34, L = 6, R = 6, ph = H - T - B;
  var y = function (v) { return T + (hi - v) * ph / (hi - lo + span * 0.0001); };
  var step = (W - L - R) / bars.length, bw = Math.min(56, step * 0.62);
  var s = '<line class="grid" x1="' + L + '" x2="' + (W - R) + '" y1="' + y(0) + '" y2="' + y(0) + '"/>';
  bars.forEach(function (b, i) {
    var cx = L + step * (i + 0.5), top = y(Math.max(b.from, b.to)), h = Math.max(1.5, Math.abs(y(b.from) - y(b.to)));
    var col = b.s.kind === 'total' ? 'var(--accent)' : b.v >= 0 ? 'var(--positive)' : 'var(--negative)';
    s += '<rect class="band' + (b.s.label === sel ? ' selected' : '') + '" data-i="' + i + '" x="' + (L + step * i) + '" y="' + T + '" width="' + step + '" height="' + ph + '" rx="4"/>';
    if (i < bars.length - 1) s += '<line class="conn" x1="' + (cx + bw / 2) + '" x2="' + (cx + step - bw / 2) + '" y1="' + y(b.run) + '" y2="' + y(b.run) + '"/>';
    s += '<rect x="' + (cx - bw / 2) + '" y="' + top + '" width="' + bw + '" height="' + h + '" rx="2" fill="' + col + '" pointer-events="none"/>';
    var below = b.s.kind !== 'total' && b.v < 0;
    s += '<text class="val" x="' + cx + '" y="' + (below ? top + h + 12 : top - 4) + '" text-anchor="middle" pointer-events="none">' + fmt(b.v) + '</text>';
    s += '<text x="' + cx + '" y="' + (H - 12) + '" text-anchor="middle" pointer-events="none">' + String(b.s.label) + '</text>';
  });
  svg.innerHTML = s;
  svg.onmouseover = function (e) {
    var i = e.target.getAttribute && e.target.getAttribute('data-i'); if (i == null) return;
    var b = bars[+i];
    tip.innerHTML = '<div><b>' + b.s.label + '</b></div><div><span>Value</span><b>' + fmt(b.v) + '</b></div><div><span>Running total</span><b>' + fmt(b.run) + '</b></div>';
    tip.hidden = false;
    var x = L + step * (+i + 0.5) + 14; if (x + 170 > W) x -= 184 + 28;
    tip.style.left = Math.max(0, x) + 'px'; tip.style.top = '10px';
  };
  svg.onmouseout = function () { tip.hidden = true; };
  svg.onclick = function (e) {
    var i = e.target.getAttribute && e.target.getAttribute('data-i'); if (i == null) return;
    fire('stepSelected', { label: bars[+i].s.label });
  };
}
